// Flatten a JSON Schema into addressable field paths: a port of src/formcast/schema.py, plus the
// placeholder records the browser demo fills in.
//
// Python is the reference. tests/web/fixtures/schema.json is generated by running the Python library
// (demo/tools/export_conformance.py) and schema.test.js holds this file to it, error messages
// included.
//
// Path syntax
//   a.b                object property b of a
//   a[]                every item of array a; a[].b is property b of each item
//   a["first name"]    property names that are empty or contain . [ ] " \ or whitespace use the
//                      quoted form; inside the quotes \" and \\ escape " and \
//   ["first name"].x   the quoted form is also valid for the first segment
//
// Schema interpretation
//   format: date becomes type date; any enum becomes type enum (non-string values are written the
//   way JSON writes them: true, 1). Nullable types are unwrapped, a union with several non-null
//   branches is its first non-null branch, allOf parts are merged, local $refs are resolved, a
//   recursive ref is emitted but not expanded again. An object emits its own path and one path per
//   property; an array emits its own path (with item_type) and, for arrays of objects, one path per
//   column under name[] with in_table set to the nearest enclosing array-of-objects path.
//
// One difference JavaScript cannot avoid: a property named like an array index ("1", "10") is placed
// first in ascending order by JSON.parse, before the other properties, so such a schema may flatten
// in a different order than Python.

import {
  codePoints,
  hasKey,
  isDict,
  pyIsSpace,
  pyJsonDumps,
  pyRepr,
  pyTruthy,
  pyUnquote,
} from "./pycompat.js";

/** Raised where Python raises FormcastError; `message` is Python's text. */
export class SchemaError extends Error {
  /** @param {string} message */
  constructor(message) {
    super(message);
    this.name = "SchemaError";
  }
}

/** Raised where Python's parse_path raises ValueError (a malformed path string). */
export class PathError extends Error {
  /** @param {string} message */
  constructor(message) {
    super(message);
    this.name = "PathError";
  }
}

/**
 * @typedef {object} SchemaPath
 * @property {string} path
 * @property {"string"|"integer"|"number"|"boolean"|"date"|"enum"|"array"|"object"} type
 * @property {string} description
 * @property {string[]|null} enum
 * @property {string|null} item_type
 * @property {string|null} in_table
 */

// ---------------------------------------------------------------- path syntax

/**
 * The `[]` path segment ("every item of the array"). A boxed string so it stays a string for printing
 * and measuring yet differs from a property literally named "[]" (compare with `===` or isArrayItem).
 */
export const ARRAY_ITEM = Object.freeze(new String("[]")); // eslint-disable-line no-new-wrappers

/**
 * True when `segment` is the array-item marker (not a property named "[]").
 * @param {string|String} segment
 * @returns {boolean}
 */
export function isArrayItem(segment) {
  return segment === ARRAY_ITEM;
}

const SPECIAL = new Set(['.', '[', ']', '"', "\\"]);

function isBare(name) {
  const chars = codePoints(name);
  return chars.length > 0 && !chars.some((c) => SPECIAL.has(c) || pyIsSpace(c));
}

function formatSegment(segment, first) {
  if (isArrayItem(segment)) return "[]";
  const name = String(segment);
  if (isBare(name)) return first ? name : `.${name}`;
  return `["${name.replaceAll("\\", "\\\\").replaceAll('"', '\\"')}"]`;
}

/**
 * Join segments into a path string (the inverse of parsePath).
 * @param {(string|String)[]} segments
 * @returns {string}
 */
export function formatPath(segments) {
  return segments.map((s, i) => formatSegment(s, i === 0)).join("");
}

/**
 * Split a path string into segments: property names as strings, array items as ARRAY_ITEM.
 * Throws PathError on a malformed path (Python's ValueError, same message).
 * @param {string} path
 * @returns {(string|String)[]}
 */
export function parsePath(path) {
  if (!path) throw new PathError("empty path");
  const chars = codePoints(path); // Python indexes by code point
  const n = chars.length;
  const segments = [];

  const bare = (start) => {
    let j = start;
    while (j < n && !SPECIAL.has(chars[j]) && !pyIsSpace(chars[j])) j += 1;
    if (j === start) throw new PathError(`expected a property name at position ${start} in ${pyRepr(path)}`);
    segments.push(chars.slice(start, j).join(""));
    return j;
  };

  const startsWith = (text, at) => chars.slice(at, at + text.length).join("") === text;

  const bracket = (start) => {
    if (startsWith("[]", start)) {
      segments.push(ARRAY_ITEM);
      return start + 2;
    }
    if (!startsWith('["', start)) {
      throw new PathError(`expected [] or ["name"] at position ${start} in ${pyRepr(path)}`);
    }
    let j = start + 2;
    const out = [];
    while (j < n) {
      const c = chars[j];
      if (c === "\\") {
        if (j + 1 >= n || !['"', "\\"].includes(chars[j + 1])) {
          throw new PathError(`bad escape at position ${j} in ${pyRepr(path)}`);
        }
        out.push(chars[j + 1]);
        j += 2;
      } else if (c === '"') {
        if (!startsWith("]", j + 1)) throw new PathError(`expected "]" after closing quote in ${pyRepr(path)}`);
        segments.push(out.join(""));
        return j + 2;
      } else {
        out.push(c);
        j += 1;
      }
    }
    throw new PathError(`unterminated quoted name in ${pyRepr(path)}`);
  };

  let i = chars[0] === "[" ? bracket(0) : bare(0);
  while (i < n) {
    if (chars[i] === ".") i = bare(i + 1);
    else if (chars[i] === "[") i = bracket(i);
    else throw new PathError(`unexpected ${pyRepr(chars[i])} at position ${i} in ${pyRepr(path)}`);
  }
  return segments;
}

// -------------------------------------------------------------------- flatten

const SCALAR_TYPES = new Set(["string", "integer", "number", "boolean"]);

function merge(a, b) {
  const out = { ...a, ...b };
  if (isDict(a.properties) && isDict(b.properties)) out.properties = { ...a.properties, ...b.properties };
  return out;
}

function lookupRef(ref, root) {
  if (!ref.startsWith("#")) {
    throw new SchemaError(`unsupported $ref ${pyRepr(ref)}: only local '#/...' refs are supported`);
  }
  if (ref === "#") return root;
  if (!ref.startsWith("#/")) {
    throw new SchemaError(`unsupported $ref ${pyRepr(ref)}: only JSON-pointer refs are supported`);
  }
  let node = root;
  for (const raw of ref.slice(2).split("/")) {
    const key = pyUnquote(raw).replaceAll("~1", "/").replaceAll("~0", "~");
    if (isDict(node) && hasKey(node, key)) node = node[key];
    else if (Array.isArray(node) && /^[0-9]+$/.test(key) && Number(key) < node.length) node = node[Number(key)];
    else throw new SchemaError(`unresolvable $ref ${pyRepr(ref)}`);
  }
  if (!isDict(node)) throw new SchemaError(`$ref ${pyRepr(ref)} does not point at a schema object`);
  return node;
}

function singleType(schema) {
  const t = schema.type;
  if (Array.isArray(t)) {
    const nonNull = t.filter((x) => x !== "null");
    return nonNull.length ? nonNull[0] : "null";
  }
  return typeof t === "string" ? t : null;
}

function inferType(schema) {
  const t = singleType(schema);
  if (t !== null) return t;
  if (isDict(schema.properties)) return "object";
  if (hasKey(schema, "items")) return "array";
  return null;
}

/**
 * Where a normalized schema's children came from: `props` maps a property name, and `items` the
 * array items, to the `$ref` stack to use when expanding that child. This keeps a ref reused by a
 * sibling branch from looking recursive, while any cycle (even one reached only through
 * allOf/anyOf/oneOf) still hits the stack.
 */
class Origin {
  constructor() {
    /** @type {Map<string, string[]>} */
    this.props = new Map();
    /** @type {string[]|null} */
    this.items = null;
  }

  /** Later sources win, mirroring `merge`. */
  absorb(other, sub) {
    for (const [name, stack] of other.props) this.props.set(name, stack);
    if (hasKey(sub, "items")) this.items = other.items;
  }
}

/**
 * Resolve $ref / allOf / anyOf / oneOf and nullable type lists.
 * @returns {[object, Origin]} a plain schema (with a single `type` when one is knowable) and the
 *   origin of its children
 */
function normalize(node, root, stack) {
  let origin = new Origin();
  if (!isDict(node)) return [{}, origin];
  let result = {};
  const ref = node.$ref;
  if (typeof ref === "string") {
    const target = lookupRef(ref, root);
    if (stack.includes(ref)) {
      // Recursive reference: keep the node's type but do not expand children.
      const shallow = Object.fromEntries(Object.entries(target).filter(([k]) => k !== "properties" && k !== "items"));
      const inferred = inferType(target);
      shallow.type = pyTruthy(inferred) ? inferred : "object";
      result = shallow;
    } else {
      [result, origin] = normalize(target, root, [...stack, ref]);
    }
  }
  // Python iterates whatever allOf holds; only a list of schemas contributes anything.
  for (const part of Array.isArray(node.allOf) ? node.allOf : []) {
    const [sub, subOrigin] = normalize(part, root, stack);
    result = merge(result, sub);
    origin.absorb(subOrigin, sub);
  }
  const union = pyTruthy(node.anyOf) ? node.anyOf : node.oneOf;
  if (Array.isArray(union) && union.length) {
    const branches = union.map((b) => normalize(b, root, stack));
    const nonNull = branches.filter(([s]) => singleType(s) !== "null");
    const [sub, subOrigin] = nonNull.length ? nonNull[0] : [{ type: "string" }, new Origin()];
    result = merge(result, sub);
    origin.absorb(subOrigin, sub);
  }
  const own = Object.fromEntries(
    Object.entries(node).filter(([k]) => k !== "$ref" && k !== "allOf" && k !== "anyOf" && k !== "oneOf"),
  );
  result = merge(result, own);
  if (isDict(own.properties)) for (const name of Object.keys(own.properties)) origin.props.set(name, stack);
  if (hasKey(own, "items")) origin.items = stack;
  const t = inferType(result);
  if (t !== null) result = { ...result, type: t };
  return [result, origin];
}

function enumValues(schema) {
  const values = schema.enum;
  if (!Array.isArray(values)) return null;
  return values.map((v) => (typeof v === "string" ? v : pyJsonDumps(v)));
}

function pathType(schema) {
  if (Array.isArray(schema.enum) && schema.type !== "object" && schema.type !== "array") return "enum";
  const t = schema.type;
  if (t === "string" && schema.format === "date") return "date";
  if (SCALAR_TYPES.has(t) || t === "object" || t === "array") return t;
  return "string"; // untyped, "null" or unknown
}

/**
 * Flatten `schema` into field paths, parents before children, in schema order.
 * Throws SchemaError where Python raises FormcastError (remote or dangling $ref, non-object root).
 * @param {object} schema
 * @returns {SchemaPath[]}
 */
export function flattenSchema(schema) {
  const [root, rootOrigin] = normalize(schema, schema, []);
  if (pathType(root) !== "object") throw new SchemaError("schema root must be an object schema");
  /** @type {SchemaPath[]} */
  const out = [];

  const children = (node, origin, segs, inTable) => {
    if (!isDict(node.properties)) return;
    for (const [name, sub] of Object.entries(node.properties)) {
      const [child, childOrigin] = normalize(sub, schema, origin.props.get(name) ?? []);
      visit([...segs, name], child, childOrigin, inTable);
    }
  };

  const visit = (segs, node, origin, inTable) => {
    const path = formatPath(segs);
    const ptype = pathType(node);
    const entry = {
      path,
      type: ptype,
      description: typeof node.description === "string" ? node.description : "",
      enum: ptype === "enum" ? enumValues(node) : null,
      item_type: null,
      in_table: inTable,
    };
    out.push(entry);
    if (ptype === "object") {
      children(node, origin, segs, inTable);
    } else if (ptype === "array") {
      const hasItems = node.items !== undefined && node.items !== null;
      const [items, itemsOrigin] = normalize(node.items, schema, origin.items ?? []);
      const itemType = hasItems ? pathType(items) : null;
      entry.item_type = itemType;
      if (itemType === "enum") entry.enum = enumValues(items);
      if (itemType === "object") children(items, itemsOrigin, [...segs, ARRAY_ITEM], path);
      else if (itemType === "array") visit([...segs, ARRAY_ITEM], items, itemsOrigin, inTable);
    }
  };

  children(root, rootOrigin, [], null);
  return out;
}

// ------------------------------------------------------------ placeholder records
// A sample record for a pasted schema, shown as editable JSON in the Fill step. Values are driven by
// the schema's types and constraints; strings take a fitting fake value when the format or the
// property name says what they are (date, email, phone, ZIP, SSN, EIN, URL) and "Sample <title or
// name>" otherwise. Arrays get two rows, fewer or more when minItems or maxItems say so.

const FAKE = {
  date: (row) => `2024-03-${String(15 + (row ?? 0)).padStart(2, "0")}`,
  email: (row) => `sample${row === null ? "" : row + 1}@example.com`,
  phone: () => "555-123-4567",
  zip: () => "12345",
  ssn: () => "123-45-6789",
  ein: () => "12-3456789",
  url: () => "https://example.com",
};

const FORMAT_FAKE = {
  date: "date",
  email: "email",
  "idn-email": "email",
  uri: "url",
  url: "url",
  "date-time": (row) => `${FAKE.date(row)}T09:30:00Z`,
  time: () => "09:30:00",
  uuid: () => "123e4567-e89b-12d3-a456-426614174000",
  ipv4: () => "192.0.2.1",
};

/** "firstName" and "first_name" both become "first name". */
function humanize(name) {
  return name.replace(/([a-z0-9])([A-Z])/g, "$1 $2").replace(/[\s_\-.]+/g, " ").trim().toLowerCase();
}

const hasWord = (...tokens) => (words) => words.some((w) => tokens.includes(w));

// what a property name says it holds, tried in this order (`words` are the lower-case words of the name)
const NAME_FAKE = [
  ["email", (words) => words.join("").includes("email")],
  ["zip", hasWord("zip", "zipcode", "postal", "postcode")],
  ["phone", hasWord("phone", "telephone", "tel", "fax", "mobile", "cell")],
  ["ssn", hasWord("ssn")],
  ["ein", hasWord("ein")],
  ["date", hasWord("date", "dob", "birthdate", "birthday")],
  ["url", hasWord("url", "website")],
];

function fakeCandidates(node, name, row) {
  const out = [];
  const byFormat = typeof node.format === "string" && hasKey(FORMAT_FAKE, node.format) ? FORMAT_FAKE[node.format] : undefined;
  if (byFormat !== undefined) out.push(typeof byFormat === "string" ? FAKE[byFormat](row) : byFormat(row));
  const words = humanize(name).split(" ");
  const named = NAME_FAKE.find(([, matches]) => matches(words));
  if (named !== undefined) out.push(FAKE[named[0]](row));
  return out;
}

/**
 * Make a string that fits a simple `pattern`: literals, \d \w \s, [0-9] [A-Z] [a-z] and other
 * character classes, ".", with the quantifiers ? + * {n} {n,m} (an optional part is included).
 * Returns null for anything with groups or alternation.
 */
function stringFromPattern(pattern) {
  let digit = 0;
  const nextDigit = () => String((digit++ % 9) + 1);
  const chars = codePoints(pattern.replace(/^\^/, "").replace(/\$$/, ""));
  let out = "";
  let i = 0;
  while (i < chars.length) {
    const c = chars[i];
    let atom;
    if (c === "\\") {
      const e = chars[i + 1];
      atom = e === "d" ? nextDigit : e === "w" ? () => "a" : e === "s" ? () => " " : () => e;
      i += 2;
    } else if (c === "[") {
      const end = chars.indexOf("]", i);
      if (end < 0) return null;
      const set = chars.slice(i + 1, end).join("");
      const first = set[0] === "^" ? "a" : set[0];
      atom = set.includes("0-9") ? nextDigit : set.includes("A-Z") ? () => "A" : () => first;
      i = end + 1;
    } else if (c === ".") {
      atom = () => "a";
      i += 1;
    } else if ("()|?+*{}".includes(c)) {
      return null;
    } else {
      atom = () => c;
      i += 1;
    }
    let count = 1;
    if ("?+*".includes(chars[i] ?? "x")) {
      i += 1;
    } else if (chars[i] === "{") {
      const end = chars.indexOf("}", i);
      const m = end < 0 ? null : /^(\d+)(?:,\d*)?$/.exec(chars.slice(i + 1, end).join(""));
      if (m === null) return null;
      count = Number(m[1]);
      i = end + 1;
    }
    for (let k = 0; k < count; k++) out += atom();
  }
  return out;
}

function fitString(value, node) {
  let chars = codePoints(value);
  if (Number.isInteger(node.maxLength) && chars.length > node.maxLength) chars = chars.slice(0, node.maxLength);
  while (Number.isInteger(node.minLength) && chars.length < node.minLength) chars.push("x");
  return chars.join("");
}

function placeholderString(node, label, name, row) {
  const text = `Sample ${label}${row === null ? "" : ` ${row + 1}`}`;
  const candidates = [...fakeCandidates(node, name, row), text];
  let pattern = null;
  if (typeof node.pattern === "string") {
    try {
      pattern = new RegExp(node.pattern, "u");
    } catch {
      pattern = null; // a pattern JavaScript cannot compile is not enforced here
    }
  }
  let chosen = candidates[0];
  if (pattern !== null) {
    const fits = candidates.find((c) => pattern.test(fitString(c, node)));
    const built = stringFromPattern(node.pattern);
    chosen = fits ?? (built !== null && pattern.test(built) ? built : candidates[0]);
  }
  return fitString(chosen, node);
}

function placeholderNumber(node, row) {
  const integer = node.type === "integer";
  const step = integer ? 1 : 0.5;
  let lo = typeof node.minimum === "number" ? node.minimum : -Infinity;
  if (typeof node.exclusiveMinimum === "number") lo = Math.max(lo, node.exclusiveMinimum + step);
  let hi = typeof node.maximum === "number" ? node.maximum : Infinity;
  if (typeof node.exclusiveMaximum === "number") hi = Math.min(hi, node.exclusiveMaximum - step);
  let value = 1 + (row ?? 0);
  if (typeof node.multipleOf === "number" && node.multipleOf > 0) value = Math.ceil(value / node.multipleOf) * node.multipleOf;
  if (value < lo) value = integer ? Math.ceil(lo) : lo;
  if (value > hi) value = integer ? Math.floor(hi) : hi;
  if (value < lo) value = lo; // an empty range: prefer the lower bound
  return value;
}

function placeholderValue(node, origin, name, root, ctx) {
  if (hasKey(node, "const")) return node.const;
  const label = typeof node.title === "string" && node.title ? node.title : humanize(name);
  if (Array.isArray(node.enum) && node.enum.length && node.type !== "object" && node.type !== "array") {
    return node.enum[ctx.unique ? ctx.row % node.enum.length : 0];
  }
  switch (node.type) {
    case "integer":
    case "number":
      return placeholderNumber(node, ctx.row);
    case "boolean":
      return true;
    case "null":
      return null;
    case "object":
      return placeholderObject(node, origin, root, ctx);
    case "array":
      return placeholderArray(node, origin, name, root, ctx);
    default:
      return placeholderString(node, label, name, ctx.row);
  }
}

function placeholderObject(node, origin, root, ctx) {
  const entries = [];
  if (isDict(node.properties)) {
    for (const [name, sub] of Object.entries(node.properties)) {
      const [child, childOrigin] = normalize(sub, root, origin.props.get(name) ?? []);
      entries.push([name, placeholderValue(child, childOrigin, name, root, { row: ctx.row, unique: false })]);
    }
  }
  return Object.fromEntries(entries);
}

function placeholderArray(node, origin, name, root, ctx) {
  const [items, itemsOrigin] = normalize(node.items, root, origin.items ?? []);
  const minItems = Number.isInteger(node.minItems) ? node.minItems : 0;
  const maxItems = Number.isInteger(node.maxItems) ? node.maxItems : Infinity;
  const count = Math.min(Math.max(2, minItems), Math.max(maxItems, 0), 10);
  const unique = node.uniqueItems === true;
  const rows = [];
  for (let row = 0; row < count; row++) {
    rows.push(placeholderValue(items, itemsOrigin, name, root, { row, unique }));
  }
  if (!unique) return rows;
  const seen = new Set();
  return rows.filter((v) => {
    const key = JSON.stringify(v);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

const PATHS = new WeakMap(); // schema object -> its flattened paths

/**
 * The flattened paths of a schema, computed once per schema object: what the panels and the page
 * view show. A missing schema, or one that can't be flattened, gives [] (the layouts report a bad
 * schema where it is entered, not on every render).
 * @param {object | null | undefined} schema
 * @returns {SchemaPath[]}
 */
export function schemaPathsOf(schema) {
  if (schema === null || typeof schema !== "object") return [];
  let paths = PATHS.get(schema);
  if (paths === undefined) {
    try {
      paths = flattenSchema(schema);
    } catch {
      paths = [];
    }
    PATHS.set(schema, paths);
  }
  return paths;
}

/**
 * A sample record for `schema`: a value at every path, shaped like the data the schema describes.
 * Strings get "Sample <title or name>" or a fitting fake value (dates are ISO, emails contain "@",
 * ZIP codes are 5 digits, a `pattern` is honoured when it is simple), numbers a small value inside
 * their range, booleans true, enums their first option, arrays two rows.
 * Throws SchemaError (as flattenSchema does) when the root is not an object schema.
 * @param {object} schema
 * @returns {object}
 */
export function placeholderRecord(schema) {
  const [root, rootOrigin] = normalize(schema, schema, []);
  if (pathType(root) !== "object") throw new SchemaError("schema root must be an object schema");
  return placeholderObject(root, rootOrigin, schema, { row: null, unique: false });
}
